"""Marker blocks that separate generated engine code from user content (SPEC §5).

A block looks like:
    <!-- DECK-ENGINE:BEGIN v0.1.0 | generated by tools/build.py - do not edit -->
    ...
    <!-- DECK-ENGINE:END -->

Every block name must occur exactly once per file. build.py writes blocks;
update.py (P6) swaps them in existing decks without touching anything else.
"""
from __future__ import annotations

import re

DECK_ENGINE = "DECK-ENGINE"      # deck: engine CSS/JS + vendored fonts and KaTeX (end of <body>)
ANIM_VENDOR = "ANIM-VENDOR"      # animation: vendored fonts and KaTeX (<head>)
ANIM_CONTRACT = "ANIM-CONTRACT"  # animation: deck contract snippet (end of <body>)

DECK_BLOCKS = (DECK_ENGINE,)
ANIM_BLOCKS = (ANIM_VENDOR, ANIM_CONTRACT)


def begin(name: str, version: str) -> str:
    return f"<!-- {name}:BEGIN v{version} | generated by tools/build.py - do not edit -->"


def end(name: str) -> str:
    return f"<!-- {name}:END -->"


def wrap(name: str, version: str, body: str) -> str:
    return f"{begin(name, version)}\n{body.strip(chr(10))}\n{end(name)}"


def block_re(name: str) -> re.Pattern:
    return re.compile(
        rf"<!-- {re.escape(name)}:BEGIN v(?P<version>[0-9A-Za-z.+\-]+) \|[^\n]*?-->"
        rf"(?P<body>.*?)"
        rf"<!-- {re.escape(name)}:END -->",
        re.S,
    )


def find(text: str, name: str) -> list[re.Match]:
    return list(block_re(name).finditer(text))


def version_of(text: str, name: str) -> str:
    matches = find(text, name)
    if len(matches) != 1:
        raise ValueError(f"expected exactly one {name} block, found {len(matches)}")
    return matches[0]["version"]


def replace(text: str, name: str, new_block: str) -> str:
    matches = find(text, name)
    if len(matches) != 1:
        raise ValueError(f"expected exactly one {name} block, found {len(matches)}")
    m = matches[0]
    return text[: m.start()] + new_block + text[m.end():]
